import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.iKZ1V-y0.js";const g=JSON.parse('{"title":"Depot-Related Priority Phenomena","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"仓库相关优先级现象","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pgnaI2HtL8UdrJqoloJQvA","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-pgnaI2HtL8UdrJqoloJQvA.md","filePath":"logistics/src/page-pgnaI2HtL8UdrJqoloJQvA.md","lastUpdated":null}'),r={name:"logistics/src/page-pgnaI2HtL8UdrJqoloJQvA.md"};function s(n,e,l,c,d,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="仓库相关优先级现象" aria-hidden="true"></span><h1 id="depot-related-priority-phenomena" tabindex="-1">Depot-Related Priority Phenomena <a class="header-anchor" href="#depot-related-priority-phenomena" aria-label="Permalink to &quot;Depot-Related Priority Phenomena&quot;">​</a></h1><blockquote><p>Source page ID: <code>pgnaI2HtL8UdrJqoloJQvA</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pgnaI2HtL8UdrJqoloJQvA" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-d5922f12e457a433.q90-04b897c52e14153c.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-fd14ff7c64c73e3f.q90-e2565d9429a53c5e.webp" alt="Image"></td></tr></tbody></table><p>In this structure, placing the two Depot Unloaders A and B again, together with the belt connected to A, gives A priority.</p><p>Replacing a Depot Loader alone may put it into a low-priority state, but this cannot be achieved reliably; the outcome and required number of attempts are uncertain.</p><p>Tests show that this phenomenon is almost always corrected after logging out, and it can usually be ignored. However, it is inconsistent; sometimes logging out instead triggers the problem.</p><p>Depot Loaders exhibit the same input-priority phenomenon as Reactor Crucibles: the first connection inputs first. The PAC also exhibits it. It is uncertain whether Reactor Crucibles have a similar phenomenon [as worded in the source]; this behavior may be stable.</p></div>',1)])])}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
